// formato único do resto do fluxo: { canal, id_externo, tipo, texto, id_clique, comando, avaliacao } e, quando vem
// foto ou documento, o arquivo (arquivo_id, arquivo_mime, arquivo_tamanho, legenda, grupo_midia)
// mensagem chega em message; clique de botão em callback_query (o texto do botão vem em data)
const clique = $json.callback_query;
const msg = clique ? clique.message : $json.message;
let texto = String(clique ? (clique.data ?? '') : (msg?.text ?? ''));
// 👍/👎 (botão da avaliação ou escrito sozinho): vai para o resumo da conversa, sem IA
const AVALIACOES = { '👍': 'positiva', '👎': 'negativa' };
const avaliacao = AVALIACOES[texto.trim()] ?? null;
// botões do resumo do chamado: abrem o chamado ou devolvem o resumo para a IA, sem IA
const BOTOES_DO_CHAMADO = { '✅ Enviar para a equipe': 'enviar_chamado', '✏️ Corrigir o resumo': 'corrigir_chamado' };
// botões do lembrete de pontos: guardam o aceite ou a recusa, sem IA
const BOTOES_DO_LEMBRETE = { '🔔 Sim, me avise': 'lembrete_sim', 'Não quero o lembrete': 'lembrete_nao' };
// o botão Iniciar do Telegram manda /start: vira a mensagem de boas-vindas, sem IA
let comando = texto.startsWith('/start') ? 'inicio' : null;
if (comando) texto = 'oi';
if (avaliacao) comando = 'avaliacao';
if (clique && BOTOES_DO_CHAMADO[texto]) comando = BOTOES_DO_CHAMADO[texto];
if (clique && BOTOES_DO_LEMBRETE[texto]) comando = BOTOES_DO_LEMBRETE[texto];

// foto ou documento do cliente (nunca do clique, que traz a mensagem do próprio bot): com chamado aberto, o
// Atalhos - Auxiliar manda o arquivo para ele. Foto chega em vários tamanhos; a última é a maior, sempre JPG
const foto = !clique && Array.isArray(msg?.photo) && msg.photo.length ? msg.photo[msg.photo.length - 1] : null;
const documento = !clique ? msg?.document ?? null : null;
const arquivo = foto
  ? { id: foto.file_id, mime: 'image/jpeg', tamanho: foto.file_size ?? 0 }
  : documento ? { id: documento.file_id, mime: documento.mime_type ?? '', tamanho: documento.file_size ?? 0 } : null;

return {
  json: {
    canal: 'telegram',
    id_externo: String(msg?.chat?.id ?? ''),
    tipo: texto.trim() ? 'texto' : 'outro', // áudio, foto e figurinha chegam sem text
    texto: texto.slice(0, 1000),
    id_clique: clique?.id ?? null, // para responder o clique (senão o botão fica girando)
    comando,
    avaliacao,
    arquivo_id: arquivo?.id ?? '',
    arquivo_mime: arquivo?.mime ?? '',
    arquivo_tamanho: arquivo?.tamanho ?? 0,
    legenda: String((!clique && msg?.caption) || '').slice(0, 1000),
    grupo_midia: (!clique && msg?.media_group_id) || '', // álbum: várias fotos, um aviso só
  },
};

// junta o texto da IA com o que as ferramentas trouxeram nesta mensagem, para o Responder montar os
// blocos de [[peca:ID]] e [[loja:ID]] com os dados do backend (foto, preço, endereço e links não vêm da IA).
// meus_pontos, extrato_pontos, meus_pedidos, lembrete_pontos ou rascunhar_chamado com 401 (conta não confirmada):
// pedir_cpf troca a resposta pelo pedido do CPF (texto_cpf, que o Texto: pedir CPF manda). Rascunho guardado: a resposta
// vira o resumo do backend, com os botões Enviar e Corrigir. [[fora_do_tema]] sai do texto e vira fora_do_tema, anotado
// no resumo anônimo da conversa. O link do carrinho vem do link_carrinho (o último que deu certo), nunca do texto da IA:
// o Responder põe no botão do [[carrinho]]
// Número na resposta que nenhuma ferramenta trouxe (nem o cliente escreveu), numa resposta com pontos, extrato ou
// pedidos: a resposta vira o dados.texto do backend, que é a resposta pronta para quando a da IA não bate
const pecas = {};
const lojas = {};
let pedirCpf = false;
let rascunho = null;
let carrinho = null;
const COM_LOGIN = ['meus_pontos', 'extrato_pontos', 'meus_pedidos', 'lembrete_pontos', 'rascunhar_chamado'];
const COM_TEXTO_PRONTO = ['meus_pontos', 'extrato_pontos', 'meus_pedidos'];
const textosProntos = new Map(); // ferramenta -> dados (a última resposta que deu certo vale)

// números soltos, sem os que fazem parte de uma palavra ou código (CLWNFC66ME); só os dígitos, para "R$ 1.234,50"
// e "1234,50" valerem o mesmo. Um dígito só ("2 peças") não conta
const numeros = (texto) => (String(texto).match(/(?<![\p{L}\d])\d+(?:[.,]\d+)*(?![\p{L}\d])/gu) ?? [])
  .map((n) => n.replace(/\D/g, '')).filter((n) => n.length >= 2);
// todos os valores de uma resposta; número do JSON (149.9) também com duas casas, como o texto mostra (149,90)
const valores = (x) => {
  if (x === null || x === undefined) return [];
  if (typeof x === 'object') return Object.values(x).flatMap(valores);
  if (typeof x === 'number') return [String(x), x.toFixed(2)];
  return [String(x)];
};
const conhecidos = new Set(numeros($('Normalizador').first().json.texto ?? ''));

for (const passo of $json.intermediateSteps ?? []) {
  const ferramenta = passo.action?.tool;
  let observacao = passo.observation;
  try {
    if (typeof observacao === 'string') observacao = JSON.parse(observacao);
  } catch {
    continue;
  }
  for (const valor of valores(observacao)) for (const n of numeros(valor)) conhecidos.add(n);
  if (!['buscar_pecas', 'lojas', 'link_carrinho', ...COM_LOGIN].includes(ferramenta)) continue;
  for (const resposta of [].concat(observacao)) {
    if (COM_LOGIN.includes(ferramenta)) {
      if (resposta?.status === 401) pedirCpf = true;
      if (COM_TEXTO_PRONTO.includes(ferramenta) && resposta?.ok && resposta.dados?.texto) textosProntos.set(ferramenta, resposta.dados);
      // o último rascunho vale (a IA pode ter refeito o resumo na mesma resposta)
      if (ferramenta === 'rascunhar_chamado' && resposta?.ok) rascunho = resposta.dados?.mensagem ?? null;
      continue;
    }
    if (ferramenta === 'link_carrinho') {
      if (resposta?.ok && resposta.dados?.link) carrinho = resposta.dados.link;
      continue;
    }
    for (const item of resposta?.dados?.items ?? []) {
      if (ferramenta === 'buscar_pecas') pecas[item.id_produto] = item;
      // lojas vem agrupado por marca: cada loja leva a marca junto
      else for (const loja of item.lojas ?? []) lojas[loja.id_unidade] = { ...loja, marca: item.marca };
    }
  }
}
const FORA_DO_TEMA = /\[\[fora_do_tema\]\]/g;
const saida = String($json.output ?? '');
let resposta = rascunho ?? saida.replace(FORA_DO_TEMA, '').trim();

const inventados = numeros(saida).filter((n) => !conhecidos.has(n));
const trocouPeloTexto = !rascunho && !pedirCpf && textosProntos.size > 0 && inventados.length > 0;
if (trocouPeloTexto) {
  // um pedido ou movimento por linha no texto do backend: vira um bloco por item
  const blocos = [...textosProntos.values()].map((dados) => String(dados.texto).split('\n').join('\n\n'));
  if (textosProntos.get('meus_pontos')?.oferecer_lembrete === true) {
    blocos.push('Quer que eu te avise por e-mail antes de os seus pontos vencerem? [[lembrete]]');
  }
  resposta = blocos.join('\n\n');
}

// pedido do CPF. Quem já estava esperando o CPF e voltou a cair na confirmação (ex.: "mas eu já mandei o CPF") recebe
// a resposta da IA ao que escreveu e, depois, como confirmar; senão a mesma mensagem sairia repetida, como se o
// assistente não tivesse lido. A confirmação vence com a conversa (30 min parada), e o texto diz isso
const VALE_ENQUANTO = 'Por segurança, a confirmação vale só enquanto a conversa está ativa: depois de 30 minutos sem '
  + 'mensagens, preciso confirmar de novo.';
const SE_PREFERIR = 'Se preferir deixar para depois, é só escrever cancelar.';
const jaEsperavaCpf = $('Registra a mensagem').first().json.dados?.etapa === 'esperando_cpf';
const falaDaIa = saida.replace(/\[\[[^\]]*\]\]/g, '').trim();
const textoCpf = jaEsperavaCpf && falaDaIa
  ? [falaDaIa, `${VALE_ENQUANTO} Se quiser ver agora, me manda o seu CPF que eu envio outro código para o e-mail do `
    + 'seu cadastro.', SE_PREFERIR].join('\n\n')
  : ['Antes, preciso confirmar que é você. 🔒', 'Me manda o seu CPF? Vou enviar um código para o e-mail do seu cadastro.',
    VALE_ENQUANTO, SE_PREFERIR].join('\n\n');

return {
  json: {
    resposta,
    pecas: Object.values(pecas),
    lojas: Object.values(lojas),
    pedir_cpf: pedirCpf && !rascunho,
    texto_cpf: pedirCpf && !rascunho ? textoCpf : null,
    confirmar_chamado: Boolean(rascunho),
    carrinho: rascunho ? null : carrinho,
    fora_do_tema: FORA_DO_TEMA.test(saida),
    // para conferir na execução quais números fizeram a resposta virar o texto pronto
    numeros_sem_fonte: trocouPeloTexto ? inventados : [],
  },
};

// a memória curta da IA (as últimas 20 trocas) no formato do chamado: { de, texto }, da mais antiga para a mais
// nova, para o atendente saber o que o cliente já falou. Os marcadores ([[peca:ID]] e outros) saem do texto
const QUEM = { human: 'cliente', user: 'cliente', ai: 'assistente', assistant: 'assistente' };
const falas = [];
for (const item of $input.all()) {
  for (const m of [].concat(item.json.messages ?? (Object.keys(item.json).length ? item.json : []))) {
    let de = null;
    let texto = null;
    if (m.human !== undefined) [de, texto] = ['cliente', m.human];
    else if (m.ai !== undefined) [de, texto] = ['assistente', m.ai];
    else {
      de = QUEM[m.type ?? m.role] ?? null;
      texto = m.data?.content ?? m.kwargs?.content ?? m.content;
    }
    texto = typeof texto === 'string' ? texto.replace(/\[\[[^\]]*\]\]/g, '').trim() : '';
    if (de && texto) falas.push({ de, texto: texto.slice(0, 1000) });
  }
}
return [{ json: { conversa: falas.slice(-40) } }];

// resposta do abrir_chamado, já como texto para o cliente. A mensagem do backend diz o número do chamado e,
// fora do horário, quando a equipe volta; erro de regra (sem resumo, chamado já aberto, sem conta) vem no detail
const r = $json;
if (r.ok) return { json: { resposta: r.dados.mensagem } };
if (!r.status || r.status >= 500) {
  return { json: { resposta: 'Estou com uma instabilidade agora e não consegui enviar para a equipe. Pode tentar de novo em alguns instantes?' } };
}
// 401: a confirmação venceu junto com o resumo (30 min parado)
if (r.status === 401) return { json: { resposta: 'Não encontrei o resumo para enviar. Pode me contar de novo o que aconteceu?' } };
return { json: { resposta: r.detail } };
